//! Synthetic audit hints generated by each Tongo operation for the pinned
//! TypeScript auditor to decrypt in `cross-tests`.

use krusty_kms_common::{serialize_ae_balance, ElGamalCiphertext};
use krusty_kms_crypto::StarkCurve;
use krusty_kms_sdk::operations::{
    fund, ragequit, transfer, withdraw, Audit, FundParams, RagequitParams, TransferParams,
    WithdrawParams,
};
use krusty_kms_sdk::TongoAccount;
use serde_json::{json, Value};
use starknet_types_core::curve::ProjectivePoint;
use starknet_types_core::felt::Felt;
use std::fs;

const USER_PRIVATE_KEY: u64 = 12_345;
const AUDITOR_PRIVATE_KEY: u64 = 98_765;
const ACCOUNT_NONCE: u64 = 7;
const TONGO_ADDRESS: u64 = 123_456_789;

fn account(balance: u128) -> TongoAccount {
    let mut account =
        TongoAccount::from_private_key(Felt::from(USER_PRIVATE_KEY), Felt::from(TONGO_ADDRESS))
            .unwrap();
    account.set_balance(balance);
    account
}

fn current_cipher(account: &TongoAccount, balance: u128) -> ElGamalCiphertext {
    let generator = StarkCurve::generator();
    ElGamalCiphertext {
        l: StarkCurve::add(
            &StarkCurve::mul(&Felt::from(balance), Some(&generator)),
            account.owner_public_key(),
        ),
        r: generator,
    }
}

fn vector(name: &str, balance: u128, audit: Audit, user_key: &ProjectivePoint) -> Value {
    let user = user_key.to_affine().unwrap();
    let cairo_hint = serialize_ae_balance(&audit.hint_ciphertext, &audit.hint_nonce)
        .unwrap()
        .into_iter()
        .map(|limb| format!("{limb:#x}"))
        .collect::<Vec<_>>();
    json!({
        "name": name,
        "balance": balance.to_string(),
        "account_nonce": ACCOUNT_NONCE.to_string(),
        "tongo_address": format!("{:#x}", Felt::from(TONGO_ADDRESS)),
        "auditor_private_key": format!("{:#x}", Felt::from(AUDITOR_PRIVATE_KEY)),
        "user_public_key": {
            "x": format!("{:#x}", user.x()),
            "y": format!("{:#x}", user.y()),
        },
        "hint_ciphertext": hex::encode(audit.hint_ciphertext),
        "hint_nonce": hex::encode(audit.hint_nonce),
        "cairo_hint": cairo_hint,
    })
}

struct Context {
    auditor_public_key: ProjectivePoint,
    nonce: Felt,
    tongo_address: Felt,
    chain_id: Felt,
    sender_address: Felt,
}

impl Context {
    fn synthetic() -> Self {
        Self {
            auditor_public_key: StarkCurve::mul_generator(&Felt::from(AUDITOR_PRIVATE_KEY)),
            nonce: Felt::from(ACCOUNT_NONCE),
            tongo_address: Felt::from(TONGO_ADDRESS),
            chain_id: Felt::from_hex_unchecked("0x534e5f5345504f4c4941"),
            sender_address: Felt::from(0xCAFEu64),
        }
    }
}

fn fund_vector(ctx: &Context) -> Value {
    let zero_account = account(0);
    let funded = fund(
        &zero_account,
        FundParams {
            amount: 100,
            nonce: ctx.nonce,
            chain_id: ctx.chain_id,
            tongo_address: ctx.tongo_address,
            sender_address: ctx.sender_address,
            auditor_pub_key: Some(ctx.auditor_public_key.clone()),
            current_balance: current_cipher(&zero_account, 0),
        },
    )
    .unwrap();
    vector(
        "fund",
        100,
        funded.audit.unwrap(),
        zero_account.owner_public_key(),
    )
}

fn transfer_vectors(
    ctx: &Context,
    funded_account: &TongoAccount,
    current_balance: &ElGamalCiphertext,
) -> [Value; 2] {
    let recipient = StarkCurve::mul_generator(&Felt::from(44u64));
    let transferred = transfer(
        funded_account,
        TransferParams {
            recipient_public_key: recipient,
            amount: 100,
            nonce: ctx.nonce,
            chain_id: ctx.chain_id,
            tongo_address: ctx.tongo_address,
            sender_address: ctx.sender_address,
            current_balance: current_balance.clone(),
            bit_size: 16,
            auditor_pub_key: Some(ctx.auditor_public_key.clone()),
        },
    )
    .unwrap();
    [
        vector(
            "transfer_balance",
            900,
            transferred.audit_balance.unwrap(),
            funded_account.owner_public_key(),
        ),
        vector(
            "transfer_amount",
            100,
            transferred.audit_transfer.unwrap(),
            funded_account.owner_public_key(),
        ),
    ]
}

fn withdraw_vector(
    ctx: &Context,
    funded_account: &TongoAccount,
    current_balance: &ElGamalCiphertext,
) -> Value {
    let withdrawn = withdraw(
        funded_account,
        WithdrawParams {
            recipient_address: Felt::from(999u64),
            amount: 100,
            nonce: ctx.nonce,
            chain_id: ctx.chain_id,
            tongo_address: ctx.tongo_address,
            sender_address: ctx.sender_address,
            current_balance: current_balance.clone(),
            bit_size: 16,
            auditor_key: Some(ctx.auditor_public_key.clone()),
        },
    )
    .unwrap();
    vector(
        "withdraw",
        900,
        withdrawn.audit.unwrap(),
        funded_account.owner_public_key(),
    )
}

fn ragequit_vector(
    ctx: &Context,
    funded_account: &TongoAccount,
    current_balance: ElGamalCiphertext,
) -> Value {
    let quit = ragequit(
        funded_account,
        RagequitParams {
            recipient_address: Felt::from(999u64),
            nonce: ctx.nonce,
            chain_id: ctx.chain_id,
            tongo_address: ctx.tongo_address,
            sender_address: ctx.sender_address,
            current_balance,
            auditor_key: Some(ctx.auditor_public_key.clone()),
        },
    )
    .unwrap();
    vector(
        "ragequit",
        0,
        quit.audit.unwrap(),
        funded_account.owner_public_key(),
    )
}

#[test]
#[ignore = "writes synthetic vectors for the pinned TypeScript auditor"]
fn generate_audit_hint_vectors() {
    let ctx = Context::synthetic();
    let funded_account = account(1_000);
    let current_balance = current_cipher(&funded_account, 1_000);
    let mut vectors = vec![fund_vector(&ctx)];
    vectors.extend(transfer_vectors(&ctx, &funded_account, &current_balance));
    vectors.push(withdraw_vector(&ctx, &funded_account, &current_balance));
    vectors.push(ragequit_vector(&ctx, &funded_account, current_balance));

    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/../../cross-audit-hint-vectors.json"
    );
    fs::write(path, serde_json::to_string_pretty(&vectors).unwrap()).unwrap();
    println!("wrote {} synthetic audit hints to {path}", vectors.len());
}
